     2→ * Auth Controller
     3→ * Authentication endpoints (mock implementation for demo)
     4→ */
     5→import { Controller, Get, Post } from '../../core/decorators';
     6→import { container } from '../../core/container';
     7→import type { FastifyRequest, FastifyReply } from 'fastify';
     8→import { eq } from 'drizzle-orm';
     9→import { users, tenants } from '../../database/schema/index';
    10→import { getAuditService } from '../../core/audit/audit.service';
    11→
    12→interface AuthRequest extends FastifyRequest {
    13→  tenantId?: string | null;
    14→  userId?: string | null;
    15→}
    16→
    17→// Mock JWT generation (in production, use proper JWT library)
    18→function generateMockToken(userId: string, tenantId: string): string {
    19→  const payload = Buffer.from(JSON.stringify({ userId, tenantId, exp: Date.now() + 86400000 })).toString('base64');
    20→  return `mock.${payload}.signature`;
    21→}
    22→
    23→@Controller('/api/auth')
    24→export class AuthController {
    25→  /**
    26→   * POST /api/auth/login - Initiate login
    27→   */
    28→  @Post('/login')
    29→  async login(request: AuthRequest, reply: FastifyReply) {
    30→    const body = request.body as any;
    31→    const db = container.resolve<any>('Database');
    32→
    33→    // Find user by email
    34→    const result = await db
    35→      .select()
    36→      .from(users)
    37→      .where(eq(users.email, body.email))
    38→      .limit(1);
    39→
    40→    if (!result.length) {
    41→      reply.code(401);
    42→      return { error: { code: 'UNAUTHORIZED', message: 'Invalid credentials' } };
    43→    }
    44→
    45→    const user = result[0];
    46→    const token = generateMockToken(user.id, user.tenantId);
    47→
    48→    // Update last login
    49→    await db.update(users).set({ lastLoginAt: new Date() }).where(eq(users.id, user.id));
    50→
    51→    // Audit login event
    52→    getAuditService().log({
    53→      tenantId: user.tenantId,
    54→      userId: user.id,
    55→      action: 'login',
    56→      resource: 'auth',
    57→      resourceId: user.id,
    58→      ipAddress: request.ip,
    59→      userAgent: request.headers['user-agent'],
    60→      metadata: { email: user.email, method: 'password' },
    61→    });
    62→
    63→    return {
    64→      data: {
    65→        token,
    66→        expiresAt: new Date(Date.now() + 86400000).toISOString(),
    67→        user: {
    68→          id: user.id,
    69→          email: user.email,
    70→          name: user.name,
    71→          role: user.role,
    72→          tenantId: user.tenantId,
    73→        },
    74→      },
    75→    };
    76→  }
    77→
    78→  /**
    79→   * POST /api/auth/callback - OAuth callback
    80→   */
    81→  @Post('/callback')
    82→  async callback(request: AuthRequest, reply: FastifyReply) {
    83→    // Mock OAuth callback - in production integrates with BankID/ID-porten
    84→    const body = request.body as any;
    85→    return {
    86→      data: {
    87→        message: 'OAuth callback processed',
    88→        provider: body.provider || 'mock',
    89→      },
    90→    };
    91→  }
    92→
    93→  /**
    94→   * GET /api/auth/session - Get current session
    95→   */
    96→  @Get('/session')
    97→  async getSession(request: AuthRequest, reply: FastifyReply) {
    98→    const db = container.resolve<any>('Database');
    99→    const userId = (request as any).userId || request.headers['x-user-id'];
   100→    const tenantId = request.tenantId || request.headers['x-tenant-id'];
   101→
   102→    if (!userId) {
   103→      reply.code(401);
   104→      return { error: { code: 'UNAUTHORIZED', message: 'No active session' } };
   105→    }
   106→
   107→    const userResult = await db.select().from(users).where(eq(users.id, userId as string)).limit(1);
   108→
   109→    if (!userResult.length) {
   110→      reply.code(401);
   111→      return { error: { code: 'UNAUTHORIZED', message: 'User not found' } };
   112→    }
   113→
   114→    const user = userResult[0];
   115→    const permissions = getPermissionsForRole(user.role);
   116→
   117→    return {
   118→      data: {
   119→        user: {
   120→          id: user.id,
   121→          email: user.email,
   122→          name: user.name,
   123→          role: user.role,
   124→          tenantId: user.tenantId,
   125→        },
   126→        expiresAt: new Date(Date.now() + 86400000).toISOString(),
   127→        permissions,
   128→      },
   129→    };
   130→  }
   131→
   132→  /**
   133→   * POST /api/auth/logout - Logout user
   134→   */
   135→  @Post('/logout')
   136→  async logout(request: AuthRequest, reply: FastifyReply) {
   137→    const userId = (request as any).userId || request.headers['x-user-id'];
   138→    const tenantId = request.tenantId || (request.headers['x-tenant-id'] as string);
   139→
   140→    if (userId && tenantId) {
   141→      getAuditService().log({
   142→        tenantId,
   143→        userId: userId as string,
   144→        action: 'logout',
   145→        resource: 'auth',
   146→        resourceId: userId as string,
   147→        ipAddress: request.ip,
   148→        userAgent: request.headers['user-agent'],
   149→      });
   150→    }
   151→
   152→    return { data: { success: true, message: 'Logged out successfully' } };
   153→  }
   154→
   155→  /**
   156→   * POST /api/auth/refresh - Refresh JWT token
   157→   */
   158→  @Post('/refresh')
   159→  async refresh(request: AuthRequest, reply: FastifyReply) {
   160→    const userId = (request as any).userId || request.headers['x-user-id'];
   161→    const tenantId = request.tenantId || (request.headers['x-tenant-id'] as string);
   162→
   163→    if (!userId || !tenantId) {
   164→      reply.code(401);
   165→      return { error: { code: 'UNAUTHORIZED', message: 'Invalid session' } };
   166→    }
   167→
   168→    const token = generateMockToken(userId as string, tenantId);
   169→
   170→    return {
   171→      data: {
   172→        token,
   173→        expiresAt: new Date(Date.now() + 86400000).toISOString(),
   174→      },
   175→    };
   176→  }
   177→
   178→  /**
   179→   * GET /api/auth/csrf - Get CSRF token
   180→   */
   181→  @Get('/csrf')
   182→  async getCsrf(request: AuthRequest, reply: FastifyReply) {
   183→    // Mock CSRF token
   184→    const csrfToken = Buffer.from(Date.now().toString()).toString('base64');
   185→    return { data: { csrfToken } };
   186→  }
   187→
   188→  /**
   189→   * POST /api/auth/email - Email/password login
   190→   */
   191→  @Post('/email')
   192→  async emailLogin(request: AuthRequest, reply: FastifyReply) {
   193→    // Same as login for demo
   194→    return this.login(request, reply);
   195→  }
   196→
   197→  /**
   198→   * GET /api/auth/providers - List auth providers
   199→   */
   200→  @Get('/providers')
   201→  async getProviders(request: AuthRequest, reply: FastifyReply) {
   202→    return {
   203→      data: [
   204→        { id: 'email', name: 'Email', enabled: true },
   205→        { id: 'bankid', name: 'BankID', enabled: false },
   206→        { id: 'idporten', name: 'ID-porten', enabled: false },
   207→        { id: 'vipps', name: 'Vipps', enabled: false },
   208→      ],
   209→    };
   210→  }
   211→}
   212→
   213→// Helper: Get permissions based on role
   214→function getPermissionsForRole(role: string): string[] {
   215→  const permissions: Record<string, string[]> = {
   216→    admin: [
   217→      'dashboard:*',
   218→      'listings:*',
   219→      'bookings:*',
   220→      'users:*',
   221→      'organizations:*',
   222→      'reports:*',
   223→      'settings:*',
   224→      'calendar:*',
   225→      'messages:*',
   226→      'seasonal-leases:*',
   227→    ],
   228→    saksbehandler: [
   229→      'dashboard:read',
   230→      'listings:*',
   231→      'bookings:*',
   232→      'organizations:read',
   233→      'reports:read',
   234→      'calendar:*',
   235→      'messages:*',
   236→      'seasonal-leases:*',
   237→    ],
   238→    user: [
   239→      'listings:read',
   240→      'bookings:read',
   241→      'bookings:create',
   242→      'messages:read',
   243→      'messages:create',
   244→    ],
   245→  };
   246→
   247→  return permissions[role] || permissions.user;
   248→}
