     5→import jwt from 'jsonwebtoken';
     6→
     7→export interface JwtPayload {
     8→  userId: string;
     9→  tenantId: string;
    10→  iat?: number;
    11→  exp?: number;
    12→  iss?: string;
    13→  aud?: string;
    14→}
    15→
    16→export interface TokenResult {
    17→  token: string;
    18→  expiresIn: number;
    19→  expiresAt: Date;
    20→}
    21→
    22→export interface VerifiedToken extends JwtPayload {
    23→  iat: number;
    24→  exp: number;
    25→  iss: string;
    26→  aud: string;
    27→}
    28→
    29→export class JwtService {
    30→  private readonly secret: string;
    31→  private readonly issuer: string = 'xala-digilist';
    32→  private readonly audience: string = 'xala-api';
    33→  private readonly algorithm: jwt.Algorithm = 'HS256';
    34→
    35→  constructor(secret: string) {
    36→    if (!secret || secret.length < 32) {
    37→      throw new Error('JWT secret must be at least 32 characters long');
    38→    }
    39→    this.secret = secret;
    40→  }
    41→
    42→  /**
    43→   * Generate a signed JWT token for a user and tenant
    44→   * @param userId - User identifier
    45→   * @param tenantId - Tenant/organization identifier
    46→   * @param expiresIn - Token expiration time in seconds (default: 24 hours)
    47→   * @returns Token result with token string and expiration info
    48→   */
    49→  generateToken(userId: string, tenantId: string, expiresIn: number = 86400): TokenResult {
    50→    if (!userId || !tenantId) {
    51→      throw new Error('userId and tenantId are required');
    52→    }
    53→
    54→    const payload: JwtPayload = {
    55→      userId,
    56→      tenantId,
    57→    };
    58→
    59→    const token = jwt.sign(payload, this.secret, {
    60→      algorithm: this.algorithm,
    61→      issuer: this.issuer,
    62→      audience: this.audience,
    63→      expiresIn,
    64→    });
    65→
    66→    const now = Math.floor(Date.now() / 1000);
    67→    const exp = now + expiresIn;
    68→
    69→    return {
    70→      token,
    71→      expiresIn,
    72→      expiresAt: new Date(exp * 1000),
    73→    };
    74→  }
    75→
    76→  /**
    77→   * Verify and decode a JWT token
    78→   * @param token - JWT token string
    79→   * @returns Verified token payload
    80→   * @throws Error if token is invalid, expired, or has invalid signature
    81→   */
    82→  verifyToken(token: string): VerifiedToken {
    83→    if (!token) {
    84→      throw new Error('Token is required');
    85→    }
    86→
    87→    try {
    88→      const decoded = jwt.verify(token, this.secret, {
    89→        algorithms: [this.algorithm],
    90→        issuer: this.issuer,
    91→        audience: this.audience,
    92→      }) as VerifiedToken;
    93→
    94→      // Ensure required fields are present
    95→      if (!decoded.userId || !decoded.tenantId) {
    96→        throw new Error('Token missing required claims');
    97→      }
    98→
    99→      return decoded;
   100→    } catch (error) {
   101→      if (error instanceof jwt.TokenExpiredError) {
   102→        throw new Error('Token has expired');
   103→      }
   104→      if (error instanceof jwt.JsonWebTokenError) {
   105→        throw new Error('Invalid token signature');
   106→      }
   107→      if (error instanceof jwt.NotBeforeError) {
   108→        throw new Error('Token not yet valid');
   109→      }
   110→      throw error;
   111→    }
   112→  }
   113→
   114→  /**
   115→   * Decode a JWT token without verification (use for debugging only)
   116→   * @param token - JWT token string
   117→   * @returns Decoded token payload or null if invalid format
   118→   */
   119→  decodeToken(token: string): JwtPayload | null {
   120→    if (!token) {
   121→      return null;
   122→    }
   123→
   124→    try {
   125→      const decoded = jwt.decode(token) as JwtPayload;
   126→      return decoded;
   127→    } catch (error) {
   128→      return null;
   129→    }
   130→  }
   131→
   132→  /**
   133→   * Refresh a token by generating a new one with the same claims
   134→   * @param token - Existing JWT token
   135→   * @param expiresIn - New expiration time in seconds
   136→   * @returns New token result
   137→   */
   138→  refreshToken(token: string, expiresIn: number = 86400): TokenResult {
   139→    const verified = this.verifyToken(token);
   140→    return this.generateToken(verified.userId, verified.tenantId, expiresIn);
   141→  }
   142→
   143→  /**
   144→   * Extract token from Authorization header
   145→   * @param authHeader - Authorization header value (e.g., "Bearer <token>")
   146→   * @returns Token string or null if invalid format
   147→   */
   148→  extractTokenFromHeader(authHeader: string | undefined): string | null {
   149→    if (!authHeader) {
   150→      return null;
   151→    }
   152→
   153→    const parts = authHeader.split(' ');
   154→    if (parts.length !== 2 || parts[0] !== 'Bearer') {
   155→      return null;
   156→    }
   157→
   158→    return parts[1];
   159→  }
   160→
   161→  /**
   162→   * Check if a token is expired without full verification
   163→   * @param token - JWT token string
   164→   * @returns true if token is expired, false otherwise
   165→   */
   166→  isTokenExpired(token: string): boolean {
   167→    const decoded = this.decodeToken(token);
   168→    if (!decoded || !decoded.exp) {
   169→      return true;
   170→    }
   171→
   172→    const now = Math.floor(Date.now() / 1000);
   173→    return decoded.exp < now;
   174→  }
   175→}
