     5→import 'reflect-metadata';
     6→
     7→// eslint-disable-next-line @typescript-eslint/no-explicit-any
     8→type Constructor<T = any> = new (...args: any[]) => T;
     9→type Factory<T = unknown> = () => T;
    10→
    11→interface Provider<T = unknown> {
    12→  token: string | symbol;
    13→  useClass?: Constructor<T>;
    14→  useFactory?: Factory<T>;
    15→  useValue?: T;
    16→  singleton?: boolean;
    17→}
    18→
    19→class Container {
    20→  private providers = new Map<string | symbol, Provider>();
    21→  private instances = new Map<string | symbol, unknown>();
    22→  private resolving = new Set<string | symbol>();
    23→
    24→  /**
    25→   * Register a provider with the container
    26→   */
    27→  register<T>(token: string | symbol, provider: Omit<Provider<T>, 'token'>): this {
    28→    this.providers.set(token, { token, ...provider } as Provider);
    29→    return this;
    30→  }
    31→
    32→  /**
    33→   * Register a class as a singleton
    34→   */
    35→  registerSingleton<T>(token: string | symbol, constructor: Constructor<T>): this {
    36→    return this.register(token, { useClass: constructor, singleton: true });
    37→  }
    38→
    39→  /**
    40→   * Register a class as transient (new instance each time)
    41→   */
    42→  registerTransient<T>(token: string | symbol, constructor: Constructor<T>): this {
    43→    return this.register(token, { useClass: constructor, singleton: false });
    44→  }
    45→
    46→  /**
    47→   * Register a constant value
    48→   */
    49→  registerValue<T>(token: string | symbol, value: T): this {
    50→    return this.register(token, { useValue: value, singleton: true });
    51→  }
    52→
    53→  /**
    54→   * Register a factory function
    55→   */
    56→  registerFactory<T>(token: string | symbol, factory: Factory<T>, singleton = true): this {
    57→    return this.register(token, { useFactory: factory, singleton });
    58→  }
    59→
    60→  /**
    61→   * Resolve a dependency from the container
    62→   */
    63→  resolve<T>(token: string | symbol): T {
    64→    // Check for circular dependency
    65→    if (this.resolving.has(token)) {
    66→      throw new Error(`Circular dependency detected for token: ${String(token)}`);
    67→    }
    68→
    69→    const provider = this.providers.get(token);
    70→    if (!provider) {
    71→      throw new Error(`No provider found for token: ${String(token)}`);
    72→    }
    73→
    74→    // Return cached singleton if available
    75→    if (provider.singleton && this.instances.has(token)) {
    76→      return this.instances.get(token) as T;
    77→    }
    78→
    79→    this.resolving.add(token);
    80→
    81→    try {
    82→      let instance: T;
    83→
    84→      if (provider.useValue !== undefined) {
    85→        instance = provider.useValue as T;
    86→      } else if (provider.useFactory) {
    87→        instance = provider.useFactory() as T;
    88→      } else if (provider.useClass) {
    89→        instance = this.createInstance(provider.useClass) as T;
    90→      } else {
    91→        throw new Error(`Invalid provider configuration for token: ${String(token)}`);
    92→      }
    93→
    94→      // Cache singleton
    95→      if (provider.singleton) {
    96→        this.instances.set(token, instance);
    97→      }
    98→
    99→      return instance;
