   107→   */
   108→  private createInstance<T>(constructor: Constructor<T>): T {
   109→    const paramTypes = Reflect.getMetadata('design:paramtypes', constructor) || [];
   110→    const injectionTokens = Reflect.getMetadata('inject:tokens', constructor) || [];
   111→
   112→    const dependencies = paramTypes.map((type: Constructor, index: number) => {
   113→      // Check for explicit @Inject token
   114→      const explicitToken = injectionTokens[index];
   115→      if (explicitToken) {
   116→        return this.resolve(explicitToken);
   117→      }
   118→
   119→      // Use type name as token
   120→      const tokenName = type?.name;
   121→      if (tokenName && this.providers.has(tokenName)) {
   122→        return this.resolve(tokenName);
   123→      }
   124→
   125→      // Try to instantiate the type directly if it's injectable
   126→      if (type && Reflect.getMetadata('injectable', type)) {
   127→        return this.createInstance(type);
   128→      }
