     5→import Fastify, { type FastifyInstance, type FastifyRequest, type FastifyReply } from 'fastify';
     6→import cors from '@fastify/cors';
     7→import 'reflect-metadata';
     8→import { container, type Constructor } from '../core/container';
     9→import { getControllerMetadata } from '../core/decorators';
    10→import { serializeError } from '../core/errors/problem-details';
    11→import { createJwtMiddleware } from '../core/auth/jwt.middleware';
    12→
    13→export interface FastifyAdapterOptions {
    14→  logger?: boolean;
    15→  prefix?: string;
    16→  adapters?: any;
    17→  jwtSecret?: string;
    18→}
    19→
    20→/**
    21→ * Create and configure Fastify app with registered controllers
    22→ */
    23→export async function createFastifyApp(
    24→  controllers: Constructor[],
    25→  options: FastifyAdapterOptions = {}
    26→): Promise<FastifyInstance> {
    27→  const app = Fastify({
    28→    logger: options.logger ?? false,
    29→    requestIdLogLabel: 'correlationId',
    30→  });
    31→
    32→  // Enable CORS for all origins
    33→  await app.register(cors, {
    34→    origin: '*', // Allow ALL origins
    35→    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    36→    allowedHeaders: '*', // Allow ALL headers
    37→  });
    38→
    39→  // Handle empty JSON bodies (fixes SDK sending Content-Type: application/json with no body)
    40→  app.addContentTypeParser('application/json', { parseAs: 'string' }, (req, body, done) => {
    41→    if (!body || body === '') {
    42→      done(null, {});
    43→      return;
    44→    }
    45→    try {
    46→      done(null, JSON.parse(body as string));
    47→    } catch (err) {
    48→      done(err as Error, undefined);
    49→    }
    50→  });
    51→
    52→  // JWT verification middleware (runs before adapters injection)
    53→  if (options.jwtSecret) {
    54→    const jwtMiddleware = createJwtMiddleware(options.jwtSecret);
    55→
    56→    app.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    57→      // Skip JWT verification for public routes and auth endpoints
    58→      const publicRoutes = [
    59→        '/api/auth/login',
    60→        '/api/auth/callback',
    61→        '/api/public',
    62→        '/health',
    63→      ];
    64→
    65→      // Check if route should skip JWT verification
    66→      const shouldSkip = publicRoutes.some((route) => request.url.startsWith(route));
    67→
    68→      if (!shouldSkip) {
    69→        // Run JWT middleware for protected routes
    70→        await jwtMiddleware(request, reply);
    71→      }
    72→    });
    73→  }
    74→
    75→  // Inject adapters into requests
    76→  if (options.adapters) {
    77→    app.decorateRequest('adapters', null);
    78→    app.decorateRequest('tenantId', null);
    79→    app.decorateRequest('userId', null);
    80→
    81→    app.addHook('onRequest', async (request: any) => {
    82→      request.adapters = options.adapters;
    83→      // Use Skien Kommune as default tenant for demo, or null for public access
    84→      request.tenantId = request.headers['x-tenant-id'] || null;
    85→      request.userId = request.headers['x-user-id'] || null;
    86→    });
    87→  }
    88→
    89→  // Request logging
    90→  if (options.adapters?.log) {
    91→    app.addHook('onRequest', async (request) => {
    92→      options.adapters.log.info('Request received', {
    93→        method: request.method,
    94→        url: request.url,
    95→        correlationId: request.id,
    96→      });
    97→    });
    98→
    99→    app.addHook('onResponse', async (request, reply) => {
   100→      options.adapters.log.info('Request completed', {
   101→        method: request.method,
   102→        url: request.url,
   103→        statusCode: reply.statusCode,
   104→        duration: reply.elapsedTime,
   105→      });
   106→    });
   107→  }
   108→
   109→  // Global error handler (RFC 7807)
   110→  app.setErrorHandler(async (error: Error, request: FastifyRequest, reply: FastifyReply) => {
   111→    options.adapters?.log?.error('Request error', {
   112→      error: error.message,
   113→      stack: error.stack,
   114→      correlationId: request.id,
   115→    });
   116→
   117→    const problemDetails = serializeError(error, request.id);
   118→    return reply
   119→      .status(problemDetails.status)
   120→      .header('Content-Type', 'application/problem+json')
   121→      .send(problemDetails);
   122→  });
   123→
   124→  // Register controllers
   125→  for (const Controller of controllers) {
   126→    await registerController(app, Controller, options.prefix);
   127→  }
   128→
   129→  return app;
   130→}
   131→
   132→/**
   133→ * Register a controller's routes with Fastify
   134→ */
   135→async function registerController(
   136→  app: FastifyInstance,
   137→  Controller: Constructor,
   138→  globalPrefix?: string
   139→): Promise<void> {
   140→  const metadata = getControllerMetadata(Controller);
   141→  const controllerInstance = container.resolve(Controller.name);
   142→  const prefix = joinPaths(globalPrefix, metadata.prefix);
   143→
   144→  for (const route of metadata.routes) {
   145→    const path = joinPaths(prefix, route.path);
   146→    const handler = (controllerInstance as any)[route.handler].bind(controllerInstance);
   147→
   148→    switch (route.method) {
   149→      case 'GET':
   150→        app.get(path, handler);
   151→        break;
   152→      case 'POST':
   153→        app.post(path, handler);
   154→        break;
   155→      case 'PUT':
   156→        app.put(path, handler);
   157→        break;
   158→      case 'PATCH':
   159→        app.patch(path, handler);
   160→        break;
   161→      case 'DELETE':
   162→        app.delete(path, handler);
   163→        break;
   164→    }
   165→  }
   166→}
   167→
   168→/**
   169→ * Join path segments, ensuring result starts with /
   170→ */
   171→function joinPaths(...paths: (string | undefined)[]): string {
   172→  const joined = paths
   173→    .filter(Boolean)
   174→    .map((p) => p!.replace(/^\/+|\/+$/g, ''))
   175→    .filter((p) => p.length > 0)
   176→    .join('/');
   177→  return joined ? `/${joined}` : '/';
   178→}
