   102→        throw new Error('Token has expired');
   103→      }
   104→      if (error instanceof jwt.JsonWebTokenError) {
   105→        throw new Error('Invalid token signature');
   106→      }
   107→      if (error instanceof jwt.NotBeforeError) {
   108→        throw new Error('Token not yet valid');
   109→      }
   110→      throw error;
   111→    }
   112→  }
   113→
   114→  /**
   115→   * Decode a JWT token without verification (use for debugging only)
   116→   * @param token - JWT token string
   117→   * @returns Decoded token payload or null if invalid format
   118→   */
   119→  decodeToken(token: string): JwtPayload | null {
   120→    if (!token) {
   121→      return null;
   122→    }
   123→
   124→    try {
   125→      const decoded = jwt.decode(token) as JwtPayload;
   126→      return decoded;
   127→    } catch (error) {
   128→      return null;
   129→    }
   130→  }
   131→
   132→  /**
   133→   * Refresh a token by generating a new one with the same claims
   134→   * @param token - Existing JWT token
   135→   * @param expiresIn - New expiration time in seconds
   136→   * @returns New token result
   137→   */
   138→  refreshToken(token: string, expiresIn: number = 86400): TokenResult {
   139→    const verified = this.verifyToken(token);
   140→    return this.generateToken(verified.userId, verified.tenantId, expiresIn);
   141→  }
   142→
   143→  /**
   144→   * Extract token from Authorization header
   145→   * @param authHeader - Authorization header value (e.g., "Bearer <token>")
   146→   * @returns Token string or null if invalid format
   147→   */
   148→  extractTokenFromHeader(authHeader: string | undefined): string | null {
   149→    if (!authHeader) {
   150→      return null;
   151→    }
   152→
   153→    const parts = authHeader.split(' ');
   154→    if (parts.length !== 2 || parts[0] !== 'Bearer') {
   155→      return null;
   156→    }
   157→
   158→    return parts[1];
   159→  }
   160→
   161→  /**
   162→   * Check if a token is expired without full verification
   163→   * @param token - JWT token string
   164→   * @returns true if token is expired, false otherwise
   165→   */
   166→  isTokenExpired(token: string): boolean {
   167→    const decoded = this.decodeToken(token);
   168→    if (!decoded || !decoded.exp) {
   169→      return true;
   170→    }
   171→
   172→    const now = Math.floor(Date.now() / 1000);
   173→    return decoded.exp < now;
   174→  }
   175→}
