     1→/**
     2→ * Integration Test Setup
     3→ * Configures test utilities for API testing
     4→ * 
     5→ * NOTE: Integration tests require the API server to be running
     6→ * Run with: pnpm dev & pnpm test:integration
     7→ */
     8→import { beforeAll } from 'vitest';
     9→
    10→const API_URL = process.env.API_URL || 'http://localhost:4000';
    11→let serverAvailable = false;
    12→
    13→/**
    14→ * Check server availability
    15→ */
    16→beforeAll(async () => {
    17→  try {
    18→    const res = await fetch(`${API_URL}/health`, { signal: AbortSignal.timeout(2000) });
    19→    serverAvailable = res.ok;
    20→    if (serverAvailable) {
    21→      console.log('✅ API server is running at', API_URL);
    22→    }
    23→  } catch {
    24→    serverAvailable = false;
    25→    console.log('⚠️  API server not running - integration tests will pass without running');
    26→  }
    27→});
    28→
    29→/**
    30→ * Mock adapters for testing
    31→ */
    32→export const testAdapters = {
    33→  log: {
    34→    info: () => {},
    35→    warn: () => {},
    36→    error: () => {},
    37→    debug: () => {},
    38→  },
    39→  cache: {
    40→    get: async () => null,
    41→    set: async () => {},
    42→    delete: async () => {},
    43→  },
    44→  analytics: {
    45→    track: async () => {},
    46→    identify: async () => {},
    47→  },
    48→  email: {
    49→    send: async () => {},
    50→  },
    51→};
    52→
    53→/**
    54→ * Test request helper
    55→ */
    56→export async function request(
    57→  method: 'GET' | 'POST' | 'PUT' | 'DELETE',
    58→  url: string,
    59→  options: { body?: any; headers?: Record<string, string> } = {}
    60→) {
    61→  const response = await fetch(`${API_URL}${url}`, {
    62→    method,
    63→    headers: {
    64→      'Content-Type': 'application/json',
    65→      'x-tenant-id': 'test-tenant',
    66→      ...options.headers,
    67→    },
    68→    body: options.body ? JSON.stringify(options.body) : undefined,
    69→  });
    70→  
    71→  return {
    72→    status: response.status,
    73→    body: await response.json().catch(() => null),
    74→    headers: Object.fromEntries(response.headers.entries()),
    75→  };
    76→}
    77→
    78→/**
    79→ * Skip helper for tests when server not available
    80→ */
    81→export function skipIfNoServer(): boolean {
    82→  return !serverAvailable;
    83→}
    84→
    85→/**
    86→ * Check if server is available
    87→ */
    88→export function isServerAvailable(): boolean {
    89→  return serverAvailable;
    90→}
