     1→/**
     2→ * JWT Authentication Flow Integration Tests
     3→ *
     4→ * E2E verification of JWT authentication:
     5→ * - Login returns proper JWT tokens
     6→ * - Tokens can be used for authenticated requests
     7→ * - Protected routes reject unauthenticated requests
     8→ */
     9→import { describe, it, expect } from 'vitest';
    10→import { request, skipIfNoServer } from './setup';
    11→
    12→describe('JWT Authentication Flow', () => {
    13→  describe('Login Flow', () => {
    14→    it('should return JWT token on successful login', async () => {
    15→      if (skipIfNoServer()) return;
    16→
    17→      // POST /api/auth/login with valid credentials
    18→      const res = await request('POST', '/api/auth/login', {
    19→        body: {
    20→          email: 'test@example.com',
    21→          password: 'password123',
    22→        },
    23→      });
    24→
    25→      // Should return 200 with token
    26→      expect(res.status).toBe(200);
    27→      expect(res.body).toBeDefined();
    28→      expect(res.body.token).toBeDefined();
    29→
    30→      // Verify JWT token format (3 parts: header.payload.signature)
    31→      const token = res.body.token;
    32→      const parts = token.split('.');
    33→      expect(parts).toHaveLength(3);
    34→
    35→      // Verify each part is non-empty and base64-encoded
    36→      parts.forEach((part: string) => {
    37→        expect(part.length).toBeGreaterThan(0);
    38→      });
    39→    });
    40→
    41→    it('should include token expiration info', async () => {
    42→      if (skipIfNoServer()) return;
    43→
    44→      const res = await request('POST', '/api/auth/login', {
    45→        body: {
    46→          email: 'test@example.com',
    47→          password: 'password123',
    48→        },
    49→      });
    50→
    51→      expect(res.status).toBe(200);
    52→      expect(res.body.expiresAt).toBeDefined();
    53→
    54→      // expiresAt should be a future timestamp
    55→      const expiresAt = new Date(res.body.expiresAt).getTime();
    56→      const now = Date.now();
    57→      expect(expiresAt).toBeGreaterThan(now);
    58→    });
    59→  });
    60→
    61→  describe('Protected Route Access with JWT', () => {
    62→    it('should allow access to protected route with valid JWT token', async () => {
    63→      if (skipIfNoServer()) return;
    64→
    65→      // Step 1: Login and get JWT token
    66→      const loginRes = await request('POST', '/api/auth/login', {
    67→        body: {
    68→          email: 'test@example.com',
    69→          password: 'password123',
    70→        },
    71→      });
    72→
    73→      expect(loginRes.status).toBe(200);
    74→      const token = loginRes.body.token;
    75→      expect(token).toBeDefined();
    76→
    77→      // Step 2: Use token in Authorization: Bearer <token> header
    78→      const sessionRes = await request('GET', '/api/auth/session', {
    79→        headers: {
    80→          'Authorization': `Bearer ${token}`,
    81→        },
    82→      });
    83→
    84→      // Step 3: Verify session is authenticated
    85→      expect(sessionRes.status).toBe(200);
    86→      expect(sessionRes.body).toBeDefined();
    87→      expect(sessionRes.body.authenticated).toBe(true);
    88→      expect(sessionRes.body.userId).toBeDefined();
    89→      expect(sessionRes.body.tenantId).toBeDefined();
    90→    });
    91→
    92→    it('should reject access to protected route without JWT token', async () => {
    93→      if (skipIfNoServer()) return;
    94→
    95→      // Attempt GET /api/auth/session without token
    96→      const res = await request('GET', '/api/auth/session', {
    97→        // No Authorization header
    98→      });
    99→
   100→      // Verify 401 Unauthorized response
   101→      expect(res.status).toBe(401);
   102→      expect(res.body).toBeDefined();
   103→
   104→      // Should return RFC 7807 Problem Details
   105→      expect(res.body.type).toBeDefined();
   106→      expect(res.body.title).toBeDefined();
   107→      expect(res.body.status).toBe(401);
   108→    });
   109→
   110→    it('should reject access with malformed JWT token', async () => {
   111→      if (skipIfNoServer()) return;
   112→
   113→      // Use malformed token
   114→      const res = await request('GET', '/api/auth/session', {
   115→        headers: {
   116→          'Authorization': 'Bearer invalid-token',
   117→        },
   118→      });
   119→
   120→      // Should return 401 Unauthorized
   121→      expect(res.status).toBe(401);
   122→      expect(res.body.status).toBe(401);
   123→    });
   124→
   125→    it('should reject access with tampered JWT token', async () => {
   126→      if (skipIfNoServer()) return;
   127→
   128→      // Step 1: Get valid token
   129→      const loginRes = await request('POST', '/api/auth/login', {
   130→        body: {
   131→          email: 'test@example.com',
   132→          password: 'password123',
   133→        },
   134→      });
   135→
   136→      const token = loginRes.body.token;
   137→      const parts = token.split('.');
   138→
   139→      // Step 2: Tamper with payload (decode, modify, re-encode)
   140→      const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());
   141→      payload.userId = 'hacker-user-id'; // Modify userId
   142→      const tamperedPayload = Buffer.from(JSON.stringify(payload)).toString('base64');
   143→      const tamperedToken = `${parts[0]}.${tamperedPayload}.${parts[2]}`;
   144→
   145→      // Step 3: Attempt to use tampered token
   146→      const res = await request('GET', '/api/auth/session', {
   147→        headers: {
   148→          'Authorization': `Bearer ${tamperedToken}`,
   149→        },
   150→      });
   151→
   152→      // Step 4: Verify request is rejected (invalid signature)
   153→      expect(res.status).toBe(401);
   154→      expect(res.body.status).toBe(401);
   155→    });
   156→  });
   157→
   158→  describe('Token Refresh', () => {
   159→    it('should issue new JWT token on refresh', async () => {
   160→      if (skipIfNoServer()) return;
   161→
   162→      // Step 1: Login and get initial token
   163→      const loginRes = await request('POST', '/api/auth/login', {
   164→        body: {
   165→          email: 'test@example.com',
   166→          password: 'password123',
   167→        },
   168→      });
   169→
   170→      const initialToken = loginRes.body.token;
   171→
   172→      // Step 2: Refresh token
   173→      const refreshRes = await request('POST', '/api/auth/refresh', {
   174→        headers: {
   175→          'Authorization': `Bearer ${initialToken}`,
   176→        },
   177→      });
   178→
   179→      // Step 3: Verify new token is issued
   180→      expect(refreshRes.status).toBe(200);
   181→      expect(refreshRes.body.token).toBeDefined();
   182→
   183→      // New token should be different from initial token
   184→      const newToken = refreshRes.body.token;
   185→      expect(newToken).not.toBe(initialToken);
   186→
   187→      // New token should be valid JWT format
   188→      const parts = newToken.split('.');
   189→      expect(parts).toHaveLength(3);
   190→    });
   191→  });
   192→});
